def prepare_pilot(apps, schema_editor):
    companies = apps.get_model('api', 'Company')
    companies.objects.using(schema_editor.connection.alias).filter(ticker__in=(
        'MSFT', 'GOOGL', 'META', 'AAPL', 'AMZN', 'NVDA', 'AVGO', 'TSLA',
        'JPM', 'V', 'JNJ', 'XOM', 'WMT', 'CAT', 'KO')).update(is_pilot=True)
    apps.get_model('api', 'CatalogRevision').objects.using(schema_editor.connection.alias).get_or_create(pk=1)


